82	// =========================================================================
83	//  Grid-stride loop helper
84	// =========================================================================
85	
86	// 64-bit global thread index / stride. The per-element step functions in
87	// csrc/algorithms/<opt>.h take `const int64_t idx`; the grid-stride loop in
88	// each launch_<opt>.cu drives them with these. The block*thread products are
89	// formed in 64-bit (cast BEFORE the multiply) so a launch covering >2^31
90	// elements cannot overflow the 32-bit product on the way to int64_t.
91	__device__ __forceinline__ int64_t grid_stride_index() {
92	    return static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
93	}
94	
95	__device__ __forceinline__ int64_t grid_stride() {
96	    return static_cast<int64_t>(gridDim.x) * blockDim.x;
97	}
