253	// -------------------------------------------------------------------------
254	//  float4 (16B) vectorized load/store helpers for the optimizer vec4 fast
255	//  paths. The element-wise optimizer math itself stays in the canonical
256	//  csrc/algorithms/<opt>.h step functions — these helpers ONLY widen the
257	//  global memory traffic (one 128-bit transaction per 4 FP32 elements
258	//  instead of four 32-bit ones), they perform no math.
259	//
260	//  ld_f32v4 / st_f32v4 are plain (cached) vector access. ldg_f32v4 takes the
261	//  read-only/__ldg path for inputs that are not written this step (e.g. the
262	//  gradient). The pointers must be 16B-aligned (guaranteed by the host-side
263	//  is_vec4_alignable() gate before the vec4 kernel is selected).
264	// -------------------------------------------------------------------------
265	
266	__device__ __forceinline__ float4 ld_f32v4(const float4* ptr) {
267	    return *ptr;
268	}
269	
270	__device__ __forceinline__ float4 ldg_f32v4(const float4* ptr) {
271	    return __ldg(ptr);
272	}
273	
274	__device__ __forceinline__ void st_f32v4(float4* ptr, float4 v) {
275	    *ptr = v;
276	}
277	
278	// Non-temporal (streaming) 16B store — bypasses L2 for write-once output.
279	__device__ __forceinline__ void stream_store_f32v4(float4* ptr, float4 v) {
280	    __stwt(reinterpret_cast<float*>(ptr) + 0, v.x);
281	    __stwt(reinterpret_cast<float*>(ptr) + 1, v.y);
282	    __stwt(reinterpret_cast<float*>(ptr) + 2, v.z);
283	    __stwt(reinterpret_cast<float*>(ptr) + 3, v.w);
284	}
