296	// =========================================================================
297	//  RoPE pair rotation (used by SG2 scan kernels).
298	//  Input: (h0, h1, cos, sin)  ->  (h0*c - h1*s, h0*s + h1*c)
299	// =========================================================================
300	
301	__device__ __forceinline__ void rope_rotate_pair(
302	    float& h0, float& h1, float cos_v, float sin_v
303	) {
304	    float h0_new = h0 * cos_v - h1 * sin_v;
305	    float h1_new = h0 * sin_v + h1 * cos_v;
306	    h0 = h0_new;
307	    h1 = h1_new;
308	}
