310	// =========================================================================
311	//  Last-block-finished pattern for cooperative reductions without grid sync.
312	//  Returns true on exactly one block; caller uses that block to publish
313	//  the final reduced value.
314	// =========================================================================
315	
316	__device__ __forceinline__ bool last_block_finished(
317	    unsigned int* __restrict__ counter,
318	    int total_blocks
319	) {
320	    __shared__ bool is_last;
321	    if (threadIdx.x == 0) {
322	        unsigned int v = atomicInc(counter, total_blocks);
323	        is_last = (v == static_cast<unsigned int>(total_blocks - 1));
324	    }
325	    __syncthreads();
326	    return is_last;
327	}
