360	// =========================================================================
361	//  §6.1 L2 persistence for per-step optimizer state (Hopper sm_90+).
362	//
363	//  Optimizer state (m, v, EMA, mu, …) is read+written every step and is the
364	//  hottest reuse in the whole pipeline. We hint the L2 cache to keep it
365	//  resident across the step via the SAFE RUNTIME API
366	//  (cudaStreamSetAttribute + cudaAccessPolicyWindow) — NOT hand-written
367	//  `createpolicy` PTX, which trips the known CUDA-13.1 ptxas lowering bug.
368	//
369	//  Use as an RAII scope around the kernel launch(es) in a host launcher:
370	//      { L2PersistScope l2(stream, exp_avg.data_ptr(), exp_avg.nbytes(),
371	//                          exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
372	//        kernel<<<...,stream>>>(...); }
373	//  On construction it carves a persisting window over the (contiguous-ish)
374	//  span covering the given buffers; on destruction it resets the policy and
375	//  releases the carve-out so the next op sees a clean L2.
376	//
377	//  Gated by ENABLE_L2_PERSIST and a runtime check: if the requested span is
378	//  larger than the device's reservable persisting-L2 (cudaDevAttrMax-
379	//  PersistingL2CacheSize, ~50 MB on H100) — or the device predates Hopper —
380	//  the scope is a no-op (and logs nothing on the hot path).
381	// =========================================================================
382	
383	#ifndef ENABLE_L2_PERSIST
384	#define ENABLE_L2_PERSIST 1
385	#endif
386	
387	class L2PersistScope {
388	public:
389	    // Up to two state buffers (the common Adam m/v case). Pass {ptr,bytes}.
390	    L2PersistScope(cudaStream_t stream,
391	                   void* p0, size_t n0,
392	                   void* p1 = nullptr, size_t n1 = 0)
393	        : stream_(stream), active_(false) {
394	#if ENABLE_L2_PERSIST
395	        if (p0 == nullptr || n0 == 0) return;
396	
397	        int dev = 0;
398	        if (cudaGetDevice(&dev) != cudaSuccess) return;
399	
400	        int cc_major = 0;
401	        cudaDeviceGetAttribute(&cc_major, cudaDevAttrComputeCapabilityMajor, dev);
402	        if (cc_major < 9) return;  // L2 residency control: Ampere+ has the API,
403	                                   // but we scope the win to Hopper sm_90 here.
404	
405	        int max_persist = 0;
406	        cudaDeviceGetAttribute(&max_persist,
407	                               cudaDevAttrMaxPersistingL2CacheSize, dev);
408	        if (max_persist <= 0) return;
409	
410	        // Build the smallest byte span covering the (assumed nearby) buffers.
411	        char* lo = static_cast<char*>(p0);
412	        char* hi = lo + n0;
413	        if (p1 != nullptr && n1 > 0) {
414	            char* lo1 = static_cast<char*>(p1);
415	            char* hi1 = lo1 + n1;
416	            if (lo1 < lo) lo = lo1;
417	            if (hi1 > hi) hi = hi1;
418	        }
419	        size_t span = static_cast<size_t>(hi - lo);
420	        // Only worthwhile (and reservable) if the span fits the persisting L2.
421	        if (span == 0 || span > static_cast<size_t>(max_persist)) return;
422	
423	        // Reserve the carve-out for persisting accesses on this stream.
424	        cudaDeviceSetLimit(cudaLimitPersistingL2CacheSize, span);
425	
426	        cudaStreamAttrValue attr = {};
427	        attr.accessPolicyWindow.base_ptr  = static_cast<void*>(lo);
428	        attr.accessPolicyWindow.num_bytes = span;
429	        attr.accessPolicyWindow.hitRatio  = 1.0f;
430	        attr.accessPolicyWindow.hitProp   = cudaAccessPropertyPersisting;
431	        attr.accessPolicyWindow.missProp  = cudaAccessPropertyStreaming;
432	        if (cudaStreamSetAttribute(
433	                stream_, cudaStreamAttributeAccessPolicyWindow, &attr)
434	            == cudaSuccess) {
435	            active_ = true;
436	        }
437	#else
438	        (void)stream; (void)p0; (void)n0; (void)p1; (void)n1;
439	#endif
440	    }
441	
442	    ~L2PersistScope() {
443	#if ENABLE_L2_PERSIST
444	        if (!active_) return;
445	        // Reset the window (num_bytes=0 disables it) and release the carve-out
446	        // so subsequent ops on this stream see a clean, fully-normal L2.
447	        cudaStreamAttrValue attr = {};
448	        attr.accessPolicyWindow.base_ptr  = nullptr;
449	        attr.accessPolicyWindow.num_bytes = 0;
450	        attr.accessPolicyWindow.hitRatio  = 0.0f;
451	        attr.accessPolicyWindow.hitProp   = cudaAccessPropertyNormal;
452	        attr.accessPolicyWindow.missProp  = cudaAccessPropertyNormal;
453	        cudaStreamSetAttribute(
454	            stream_, cudaStreamAttributeAccessPolicyWindow, &attr);
455	        cudaCtxResetPersistingL2Cache();
456	        cudaDeviceSetLimit(cudaLimitPersistingL2CacheSize, 0);
457	#endif
458	    }
459	
460	    L2PersistScope(const L2PersistScope&) = delete;
461	    L2PersistScope& operator=(const L2PersistScope&) = delete;
462	
463	    bool active() const { return active_; }
464	
465	private:
466	    cudaStream_t stream_;
467	    bool active_;
468	};
