470	// =========================================================================
471	//  §4.2 cp.async background loads (NVIDIA PTX maximization).
472	//
473	//  Hand-issued `cp.async.{cg,ca}.shared.global` + commit/wait pipelines for
474	//  memory-bound global->shared staging loads. The async copy lets the SM
475	//  issue the load and continue executing (address math, the previous tile's
476	//  compute) while the bytes arrive — overlapping the global-load latency
477	//  instead of stalling at a synchronous load.
478	//
479	//  Contract / correctness (CRITICAL):
480	//    issue (cp_async_cg_16 / cp_async_ca_4)  ->  cp_async_commit()  ->
481	//    cp_async_wait_group<N>()  ->  __syncthreads()  ->  read shared.
482	//  A correctly WAITED cp.async produces byte-identical shared data to a plain
483	//  synchronous load. A missing/misplaced wait = reading bytes still in flight
484	//  = garbage. Every issued group MUST be committed and the consume MUST be
485	//  preceded by a wait that drains the group(s) feeding it.
486	//
487	//  Arch guard: cp.async is sm_80+ (Ampere). On pre-Ampere arches in the
488	//  codegen matrix the helpers fall back to a plain synchronous copy (commit /
489	//  wait become no-ops), so call sites are portable and numerically identical.
490	//
491	//  Alignment/size: cp.async sources must be 4/8/16-byte aligned and the size
492	//  must be exactly 4/8/16. Use cp_async_cg_16 for 16B (float4, .cg cache-
493	//  global) and cp_async_ca_4 for 4B (single float, .ca cache-all).
494	// =========================================================================
495	
496	// 16-byte (float4) async global->shared copy, .cg (cache-global) hint.
497	__device__ __forceinline__ void cp_async_cg_16(
498	    void* smem_ptr, const void* gmem_ptr
499	) {
500	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
501	    unsigned s = __cvta_generic_to_shared(smem_ptr);
502	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
503	                 :: "r"(s), "l"(gmem_ptr));
504	#else
505	    *reinterpret_cast<float4*>(smem_ptr) =
506	        *reinterpret_cast<const float4*>(gmem_ptr);
507	#endif
508	}
509	
510	// 4-byte async global->shared copy, .ca (cache-all) hint. For scalar (float)
511	// staging loops that are not float4-alignable.
512	__device__ __forceinline__ void cp_async_ca_4(
513	    void* smem_ptr, const void* gmem_ptr
514	) {
515	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
516	    unsigned s = __cvta_generic_to_shared(smem_ptr);
517	    asm volatile("cp.async.ca.shared.global [%0], [%1], 4;\n"
518	                 :: "r"(s), "l"(gmem_ptr));
519	#else
520	    *reinterpret_cast<float*>(smem_ptr) =
521	        *reinterpret_cast<const float*>(gmem_ptr);
522	#endif
523	}
