549	// =========================================================================
550	//  §3.2 DSMEM cross-CTA reductions (NVIDIA memory features — Hopper sm_90+).
551	//
552	//  Hopper thread-block clusters give every CTA in the cluster a window into
553	//  every peer CTA's shared memory ("distributed shared memory", DSMEM). A
554	//  block-reduced partial sum that lives in one CTA's shared memory can be read
555	//  by any other CTA in the same cluster via `cl.map_shared_rank(ptr, rank)`,
556	//  with a cluster barrier (`cl.sync()`) ordering the publish vs the read. This
557	//  replaces a cross-block global atomicAdd (round-trip through L2/DRAM) with an
558	//  on-chip SM-to-SM shared-memory exchange when the producing blocks all fit in
559	//  one cluster.
560	//
561	//  FULL MULTI-LEVEL TREE (§3.4):   thread -> warp -> block(shared) -> cluster.
562	//    1. warp_reduce_sum_f32   (butterfly shuffle)            — thread -> warp
563	//    2. shared-mem tree        (block_reduce_sum_f32 body)    — warp  -> block
564	//    3. publish block partial to OWN cluster_smem slot; cl.sync()
565	//    4. every block reads ALL peers' slots via map_shared_rank and sums them
566	//       (a full cluster-wide tree, not a single-rank gather); cl.sync()
567	//  Every block returns the SAME cluster-wide sum, so any block may publish the
568	//  final result (mirrors the old "block 0 atomicAdds" contract — but without
569	//  the atomic).
570	//
571	//  CORRECTNESS / ORDERING (CRITICAL):  write own slot -> cl.sync() -> read all
572	//  peers -> cl.sync(). The first barrier guarantees every peer's partial is
573	//  visible before any block reads it; the second guarantees no block reuses /
574	//  overwrites the scratch (e.g. a subsequent reduction with the same buffer)
575	//  until all reads have completed. A missing barrier == data race == garbage.
576	//
577	//  cluster_size == 1 (kernel launched WITHOUT a cluster dim — the common case)
578	//  degrades to exactly block_reduce_sum_f32: num_blocks()==1, the loop reads
579	//  only the local slot, and cl.sync() on a singleton cluster is a no-op that
580	//  CANNOT deadlock. Pre-Hopper (__CUDA_ARCH__ < 900) compiles to the plain
581	//  block reduce with no cluster API referenced at all.
582	//
583	//  NUMERICS:  the cluster gather sums block partials in rank order in fp32.
584	//  This is a tree reduction whose summation ORDER differs from the global-
585	//  atomic path (atomic completion order is nondeterministic anyway), so fp32
586	//  results may differ in the last ~1 ulp — the SAME class of reorder as the
587	//  existing warp/block shuffle trees, and within optimizer tolerance. It is
588	//  NOT bit-identical to the serial/atomic path; the on-silicon check in
589	//  HARDWARE_VALIDATION.md is a tolerance (relative-error) check, not bit-parity.
590	//
591	//  CLUSTER-SIZE CAP:  supports cluster volumes up to 8 (Hopper hw max is 8 for
592	//  portable launch; 16 is opt-in datacenter-only). The autotuner picks the
593	//  launch cluster shape via SG_TUNED_CLUSTER_SHAPE (compile.py, capped m*n*p<=8)
594	//  — see launch glue. Inside a PERSISTENT MEGAKERNEL, cap the cluster at <=2:
595	//  large clusters reduce the number of concurrently-resident cluster slots and
596	//  can starve a long-lived persistent grid (documented caveat, §3.3).
597	//
598	//  ENGINEER TOGGLE (§3.5):  ENABLE_DSMEM_REDUCE gates whether call sites take
599	//  the cluster path at all. When 0 (default), call sites keep the existing
600	//  global-atomic reduction and this helper is never invoked — ZERO overhead at
601	//  small scale. When 1, the launch glue issues a cluster launch (cudaLaunch-
602	//  KernelEx with a cluster dim, or a __cluster_dims__ kernel) and calls this
603	//  helper instead of the atomic. Default OFF because (a) it requires a cluster
604	//  launch + scratch wiring and (b) the atomic path is already correct and
605	//  bit-stable; flip to 1 once on-silicon ncu DSMEM metrics are validated.
606	// =========================================================================
607	
608	#ifndef ENABLE_DSMEM_REDUCE
609	#define ENABLE_DSMEM_REDUCE 0
610	#endif
611	
612	// Largest cluster volume this helper will gather over. Hopper hw max is 8 for
613	// the portable (compute_90a) launch path; the gather loop is bounded by the
614	// runtime num_blocks() so smaller clusters (incl. size 1) are handled too.
615	#ifndef SG_DSMEM_MAX_CLUSTER
616	#define SG_DSMEM_MAX_CLUSTER 8
617	#endif
618	
619	// Full multi-level tree reduction: thread -> warp -> block -> cluster (DSMEM).
620	//
621	//   val                 : this thread's contribution.
622	//   cluster_smem_scratch : pointer to ONE float in THIS block's shared memory,
623	//                          used as this block's published partial slot. Must be
624	//                          a real __shared__ float (so map_shared_rank can
625	//                          remap it across ranks). Caller allocates it.
626	//
627	// Returns the cluster-wide sum on every thread of every block. cluster_size==1
628	// returns the block reduce. Pre-Hopper falls back to block_reduce_sum_f32.
629	__device__ __forceinline__ float cluster_reduce_sum_f32_dsmem(
630	    float val, float* cluster_smem_scratch
631	) {
632	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
633	    // ── Levels 1+2: thread -> warp -> block, into THIS block's slot. ──────
634	    float block_partial = block_reduce_sum_f32(val);
635	    if (threadIdx.x == 0) {
636	        *cluster_smem_scratch = block_partial;
637	    }
638	
639	    // ── Level 3: cluster handle + publish barrier. ───────────────────────
640	    cg::cluster_group cluster = cg::this_cluster();
641	    const unsigned cluster_size = cluster.num_blocks();
642	
643	    // Singleton cluster (no cluster launch, the common case): the block
644	    // partial IS the answer. cl.sync() on a size-1 cluster is a safe no-op,
645	    // but short-circuit to avoid even touching the gather loop.
646	    if (cluster_size <= 1) {
647	        // block_reduce_sum_f32 already __syncthreads()'d; broadcast the slot.
648	        return block_partial;
649	    }
650	
651	    // Publish: every block has now written its slot. Barrier so all peers'
652	    // partials are visible before any read.
653	    cluster.sync();
654	
655	    // ── Level 4: gather ALL peers' slots via DSMEM (map_shared_rank). ─────
656	    // Full cluster-wide tree across ranks (bounded by SG_DSMEM_MAX_CLUSTER so
657	    // the loop is statically unrollable; runtime num_blocks() guards the tail).
658	    float total = 0.0f;
659	    #pragma unroll
660	    for (unsigned r = 0; r < SG_DSMEM_MAX_CLUSTER; ++r) {
661	        if (r >= cluster_size) break;
662	        // Remap THIS block's scratch address into peer rank r's shared window.
663	        const float* peer = cluster.map_shared_rank(cluster_smem_scratch, r);
664	        total += *peer;
665	    }
666	
667	    // Second barrier: no block may overwrite the scratch (e.g. on a subsequent
668	    // reduction reusing the same buffer) until every block finished reading.
669	    cluster.sync();
670	    return total;
671	#else
672	    // Pre-Hopper: no cluster hardware. The scratch is unused; the block reduce
673	    // is the full answer for a single-block-per-reduction launch.
674	    (void)cluster_smem_scratch;
675	    return block_reduce_sum_f32(val);
676	#endif
677	}
