470	//  LayoutB-parameterised Sm90 collective GEMM (TMA + WGMMA, FP32 accumulate)
471	//
472	//  Identical builder to Sm90Gemm above, but the B operand layout is a
473	//  template parameter. This lets callers express both flavours of the
474	//  transformer/ViT matmuls with the SAME proven CollectiveBuilder path used
475	//  by the FMHA wrappers in attention_sm90.cuh:
476	//    - LayoutBT = cutlass::layout::RowMajor    => C = A · B   (physical [K,N])
477	//    - LayoutBT = cutlass::layout::ColumnMajor => C = A · Bᵀ  (physical [N,K]
478	//                                                 row-major, e.g. a Linear
479	//                                                 weight W[out,in] read as Wᵀ)
480	//  A is always RowMajor [M,K]; C is RowMajor [M,N]; FP32 accumulate + FP32
481	//  output (matches the cuBLAS CUBLAS_COMPUTE_32F numerics). strideB packs the
482	//  logical {N, K, 1} extents so it matches the physical row-major [N,K] (Bᵀ)
483	//  / [K,N] (B) buffer respectively — same convention as fmha_sm90_gemm.
484	// ─────────────────────────────────────────────────────────────────────────
485	template <typename ElementInput, typename LayoutBT>
486	struct Sm90GemmBT {
487	    using ElementA   = ElementInput;
488	    using ElementB   = ElementInput;
489	    using ElementC   = float;          // FP32 output (matches cuBLAS path)
490	    using ElementAcc = float;          // FP32 accumulate
491	    using LayoutA    = cutlass::layout::RowMajor;
492	    using LayoutB    = LayoutBT;
493	    using LayoutC    = cutlass::layout::RowMajor;
494	
495	    static constexpr int AlignA = 128 / cutlass::sizeof_bits<ElementA>::value;
496	    static constexpr int AlignB = 128 / cutlass::sizeof_bits<ElementB>::value;
497	    static constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementC>::value;
498	
499	    using TileShape    = cute::Shape<cute::_128, cute::_128, cute::_64>;
500	    using ClusterShape = cute::Shape<cute::_1, cute::_1, cute::_1>;
501	
502	    using CollectiveEpilogue =
503	        typename cutlass::epilogue::collective::CollectiveBuilder<
504	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
505	            TileShape, ClusterShape,
506	            cutlass::epilogue::collective::EpilogueTileAuto,
507	            ElementAcc, ElementAcc,
508	            ElementC, LayoutC, AlignC,
509	            ElementC, LayoutC, AlignC,
510	            cutlass::epilogue::collective::EpilogueScheduleAuto
511	        >::CollectiveOp;
512	
513	    using CollectiveMainloop =
514	        typename cutlass::gemm::collective::CollectiveBuilder<
515	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
516	            ElementA, LayoutA, AlignA,
517	            ElementB, LayoutB, AlignB,
518	            ElementAcc,
519	            TileShape, ClusterShape,
520	            cutlass::gemm::collective::StageCountAutoCarveout<
521	                static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
522	            cutlass::gemm::collective::KernelScheduleAuto
523	        >::CollectiveOp;
524	
525	    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
526	        cute::Shape<int, int, int, int>,
527	        CollectiveMainloop,
528	        CollectiveEpilogue>;
529	
530	    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
531	};
