637	// ─────────────────────────────────────────────────────────────────────────
638	//  A-transposed Sm90 collective GEMM (TMA + WGMMA, FP32 accumulate)
639	//
640	//  C[MxN] = op(A) · B with op(A)=Aᵀ. The B operand is RowMajor [K,N]; the A
641	//  operand is ColumnMajor over the logical (M,K) extents — i.e. it reads a
642	//  physical row-major [K,M] buffer as Aᵀ (mirror of Sm90GemmBT's ColumnMajor-B
643	//  Bᵀ trick, but applied to the A operand). C is RowMajor [M,N], FP32 acc/out.
644	//
645	//  Used by the ViT wgrad: dW[N,K] = Σ_m dY[m,n] X[m,k]. In GEMM terms
646	//  (M_g=N, N_g=K, K_g=M): A=dY is physically [M,N] row-major and must be read
647	//  as Aᵀ of logical [M_g=N, K_g=M] → ColumnMajor A; B=X is physically [M,K]
648	//  row-major = logical [K_g=M, N_g=K] → RowMajor B. Sm90GemmBT can't express
649	//  this (its A is fixed RowMajor), hence this dedicated A-transposed builder.
650	//  The shape-keyed operator cache (sm90_run_gemm_cached) is fully generic over
651	//  the layouts (StrideA/B/C are derived from the Gemm type), so it serves this
652	//  builder unchanged — its per-instantiation slot table keeps the
653	//  ColumnMajor-A descriptors separate from the RowMajor-A ones.
654	// ─────────────────────────────────────────────────────────────────────────
655	template <typename ElementInput>
656	struct Sm90GemmAT {
657	    using ElementA   = ElementInput;
658	    using ElementB   = ElementInput;
659	    using ElementC   = float;          // FP32 output (matches cuBLAS/scalar path)
660	    using ElementAcc = float;          // FP32 accumulate
661	    using LayoutA    = cutlass::layout::ColumnMajor;   // reads physical [K,M] as Aᵀ
662	    using LayoutB    = cutlass::layout::RowMajor;
663	    using LayoutC    = cutlass::layout::RowMajor;
664	
665	    static constexpr int AlignA = 128 / cutlass::sizeof_bits<ElementA>::value;
666	    static constexpr int AlignB = 128 / cutlass::sizeof_bits<ElementB>::value;
667	    static constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementC>::value;
668	
669	    using TileShape    = cute::Shape<cute::_128, cute::_128, cute::_64>;
670	    using ClusterShape = cute::Shape<cute::_1, cute::_1, cute::_1>;
671	
672	    using CollectiveEpilogue =
673	        typename cutlass::epilogue::collective::CollectiveBuilder<
674	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
675	            TileShape, ClusterShape,
676	            cutlass::epilogue::collective::EpilogueTileAuto,
677	            ElementAcc, ElementAcc,
678	            ElementC, LayoutC, AlignC,
679	            ElementC, LayoutC, AlignC,
680	            cutlass::epilogue::collective::EpilogueScheduleAuto
681	        >::CollectiveOp;
682	
683	    using CollectiveMainloop =
684	        typename cutlass::gemm::collective::CollectiveBuilder<
685	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
686	            ElementA, LayoutA, AlignA,
687	            ElementB, LayoutB, AlignB,
688	            ElementAcc,
689	            TileShape, ClusterShape,
690	            cutlass::gemm::collective::StageCountAutoCarveout<
691	                static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
692	            cutlass::gemm::collective::KernelScheduleAuto
693	        >::CollectiveOp;
694	
695	    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
696	        cute::Shape<int, int, int, int>,
697	        CollectiveMainloop,
698	        CollectiveEpilogue>;
699	
700	    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
701	};
