753	// BF16 in / FP32 acc / FP32 out variant.
754	// Sm90 collective (TMA+WGMMA), FP32 accumulate — replaces the old Gemm<>
755	// that silently defaulted to Sm70 SIMT (no tensor cores).
756	inline cudaError_t gemm_bf16(
757	    int M, int N, int K,
758	    const __nv_bfloat16* A, const __nv_bfloat16* B, float* C,
759	    cudaStream_t stream)
760	{
761	    return sm90_run_gemm<cutlass::bfloat16_t>(M, N, K, A, B, C, stream);
762	}
763	
764	// ─────────────────────────────────────────────────────────────────────────
765	//  TF32 (tfloat32_t) tensor-core GEMM — the FP32 tensor-core path (LIVE).
766	//
767	//  FP32 inputs (plain `float` buffers) are fed to the Sm90 WGMMA mainloop with
768	//  ElementA/B = cutlass::tfloat32_t. tfloat32_t is a 4-byte type that occupies
769	//  the SAME storage as `float`; the WGMMA hardware rounds each operand's
770	//  mantissa to TF32's 10 explicit bits at MMA-issue time, accumulating in FP32.
771	//  So a `const float*` is reinterpret_cast to `const tfloat32_t*` (standard
772	//  CUTLASS idiom — no separate conversion buffer needed) and the result lands
773	//  in an FP32 C buffer, matching the FP32 output of the cuBLAS/scalar path.
774	//
775	//  PRECISION NOTE (🟡 numeric parity vs scalar FP32): TF32 carries a 10-bit
776	//  mantissa vs FP32's 23. This is the accepted, expected tensor-core "FP32"
777	//  mode (same precision class as cuBLAS CUBLAS_TF32_TENSOR_OP_MATH and
778	//  PyTorch's allow_tf32), NOT bit-identical to a scalar FP32 triple-loop. It is
779	//  an accuracy/precision tradeoff, not a bug. Callers demanding exact FP32 must
780	//  force the scalar path (the models gate this via SG_FORCE_SCALAR_FP32).
781	//
782	//  ALIGNMENT: tfloat32_t is 32-bit, so 128-bit vector access = 4 elements
783	//  (AlignA/B = 128/32). The Sm90 TF32 MMA atom (SM90_MMA_TF32) is selected
784	//  automatically by CollectiveBuilder<arch::Sm90, OpClassTensorOp, tfloat32_t,
785	//  ...>. Tile/cluster shapes are the same proven 128x128x64 / 1x1x1 used by the
786	//  half/bf16 builders above.
787	// ─────────────────────────────────────────────────────────────────────────
788	
789	// Run a single row-major C = A*B with FP32 (TF32 MMA) accumulate. A/B/C are
790	// plain float buffers; A and B are reinterpreted as tfloat32_t for the WGMMA.
791	inline cudaError_t sm90_run_gemm_tf32(
792	    int M, int N, int K,
793	    const float* A, const float* B, float* C,
794	    cudaStream_t stream)
795	{
796	    using G          = Sm90Gemm<cutlass::tfloat32_t>;
797	    using Gemm       = typename G::Gemm;
798	    using ElementAcc = typename G::ElementAcc;
799	    return sm90_run_gemm_cached<Gemm, cutlass::tfloat32_t, cutlass::tfloat32_t,
800	                                ElementAcc>(
801	        M, N, K, reinterpret_cast<const void*>(A),
802	        reinterpret_cast<const void*>(B), C, stream);
803	}
804	
805	// LayoutB-parameterised TF32 variant: C[MxN] = A[MxK] · op(B), op(B) is B
806	// (LayoutBT=RowMajor) or Bᵀ (LayoutBT=ColumnMajor). FP32 buffers in/out, TF32
807	// MMA. Mirrors sm90_run_gemm_bt but with the tfloat32_t element type.
808	template <typename LayoutBT>
809	inline cudaError_t sm90_run_gemm_tf32_bt(
810	    int M, int N, int K,
811	    const float* A, const float* B, float* C,
812	    cudaStream_t stream)
813	{
814	    using G          = Sm90GemmBT<cutlass::tfloat32_t, LayoutBT>;
815	    using Gemm       = typename G::Gemm;
816	    using ElementAcc = typename G::ElementAcc;
817	    return sm90_run_gemm_cached<Gemm, cutlass::tfloat32_t, cutlass::tfloat32_t,
818	                                ElementAcc>(
819	        M, N, K, reinterpret_cast<const void*>(A),
820	        reinterpret_cast<const void*>(B), C, stream);
821	}
822	
823	// FP32 in / FP32 acc / FP32 out via the TF32 tensor-core mainloop (row-major).
824	inline cudaError_t gemm_tf32(
825	    int M, int N, int K,
826	    const float* A, const float* B, float* C,
827	    cudaStream_t stream)
828	{
829	    return sm90_run_gemm_tf32(M, N, K, A, B, C, stream);
830	}
831	
832	// Softplus+bias post-pass (used by SG2 dt_proj fused path).
833	static __global__ void softplus_bias_kernel(
834	    float* __restrict__ C, const float* __restrict__ bias,
835	    int M, int N)
836	{
837	    // 64-bit linear index: M*N (rows * d_inner for the SG2 dt_proj fused path)
838	    // can exceed INT_MAX for large parameter tensors. col stays in int (col<N).
839	    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
840	    if (idx < static_cast<int64_t>(M) * N) {
841	        int col = static_cast<int>(idx % N);
842	        float val = C[idx] + bias[col];
843	        C[idx] = (val > 20.0f) ? val : logf(1.0f + expf(val));
844	    }
845	}
846	
847	inline void launch_softplus_bias(
848	    float* C, const float* bias, int M, int N,
849	    cudaStream_t stream)
850	{
851	    if (!bias) return;
852	    int64_t total = static_cast<int64_t>(M) * N;
853	    int block = 256;
854	    int grid = static_cast<int>((total + block - 1) / block);
855	    softplus_bias_kernel<<<grid, block, 0, stream>>>(C, bias, M, N);
856	}
857	
858	// Fused dt_proj: GEMM + softplus+bias in one call.
859	inline cudaError_t dt_proj_fused_with_bias(
860	    int M, int N, int K,
861	    const __half* A, const __half* B,
862	    const float* bias, float* C,
863	    cudaStream_t stream)
864	{
865	    cudaError_t err = gemm_fp16(M, N, K, A, B, C, stream);
866	    if (err != cudaSuccess) return err;
867	    launch_softplus_bias(C, bias, M, N, stream);
868	    return cudaSuccess;
869	}
