126	// Pipelined variant: producer/consumer warpgroup split staging K-tiles through
127	// an mbarrier ring (tile_pipeline.cuh), proving the choreography. Same numerics
128	// as the unpipelined kernel above (gate c). Uses blockDim.x = 256 (WG0
129	// producer + WG1 consumer).
130	template <int N, int PipeDepth>
131	__global__ void __launch_bounds__(256)
132	gemm_pipelined_kernel(
133	    const __nv_bfloat16* __restrict__ gA,
134	    const __nv_bfloat16* __restrict__ gB,
135	    float* __restrict__ gD,
136	    int k_steps
137	) {
138	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
139	    wgs::tc_pipelined_gemm_m64nNk16<N, PipeDepth>(gA, gB, gD, k_steps);
140	#else
141	    (void)gA; (void)gB; (void)gD; (void)k_steps;
142	#endif
143	}
